131	  private GenericRecord convertJsonToAvro(Map<String, Object> inputJson, Schema schema) {
132	    GenericRecord avroRecord = new GenericData.Record(schema);
133	    for (Schema.Field f : schema.getFields()) {
134	      Object val = shouldSanitize ? getFieldFromJson(f, inputJson, schema.getFullName(), invalidCharMask) : inputJson.get(f.name());
135	      if (val != null) {
136	        avroRecord.put(f.pos(), convertJsonField(val, f.name(), f.schema()));
137	      }
138	    }
139	    return avroRecord;
140	  }
