56	  protected static Pair<Boolean, BigDecimal> parseObjectToBigDecimal(Object obj, Schema schema) {
57	    BigDecimal bigDecimal = null;
58	    LogicalTypes.Decimal logicalType = (LogicalTypes.Decimal) schema.getLogicalType();
59	    try {
60	      if (obj instanceof BigDecimal) {
61	        bigDecimal = ((BigDecimal) obj).setScale(logicalType.getScale(), RoundingMode.UNNECESSARY);
62	      } else if (obj instanceof String) {
63	        // Case 2: Object is a number in String format.
64	        try {
65	          //encoded big decimal
66	          bigDecimal = HoodieAvroUtils.convertBytesToBigDecimal(decodeStringToBigDecimalBytes(obj),
67	              (LogicalTypes.Decimal) schema.getLogicalType());
68	        } catch (IllegalArgumentException e) {
69	          //no-op
70	        }
71	      }
72	      // None fixed byte or fixed byte conversion failure would end up here.
73	      if (bigDecimal == null) {
74	        bigDecimal = new BigDecimal(obj.toString(), new MathContext(logicalType.getPrecision(), RoundingMode.UNNECESSARY)).setScale(logicalType.getScale(), RoundingMode.UNNECESSARY);
75	      }
76	    } catch (java.lang.NumberFormatException | ArithmeticException ignored) {
77	      /* ignore */
78	    }
79	
80	    if (bigDecimal == null) {
81	      return Pair.of(false, null);
82	    }
83	    // As we don't do rounding, the validation will enforce the scale part and the integer part are all within the
84	    // limit. As a result, if scale is 2 precision is 5, we only allow 3 digits for the integer.
85	    // Allowed: 123.45, 123, 0.12
86	    // Disallowed: 1234 (4 digit integer while the scale has already reserved 2 digit out of the 5 digit precision)
87	    //             123456, 0.12345
88	    LogicalTypes.Decimal decimalType = (LogicalTypes.Decimal) schema.getLogicalType();
